        m.put("CleanYourTV (Beta) runs the CleanYourTV debloat profiles directly on your TV over Local ADB without needing a PC. Choose your TV model (or scan by installed system app packages), disable stock launchers or bloatware, and restore them anytime with one tap.", "CleanYourTV (\u05d1\u05d8\u05d0) \u05de\u05e8\u05d9\u05e5 \u05d0\u05ea \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9 \u05d4\u05e1\u05e8\u05ea \u05d4\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05d4\u05de\u05d9\u05d5\u05ea\u05e8\u05d5\u05ea \u05e9\u05dc CleanYourTV \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea ADB \u05de\u05e7\u05d5\u05de\u05d9, \u05dc\u05dc\u05d0 \u05e6\u05d5\u05e8\u05da \u05d1\u05de\u05d7\u05e9\u05d1. \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d0\u05ea \u05d3\u05d2\u05dd \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 (\u05d0\u05d5 \u05dc\u05e1\u05e8\u05d5\u05e7 \u05dc\u05e4\u05d9 \u05d7\u05d1\u05d9\u05dc\u05d5\u05ea \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05e7\u05e0\u05d5\u05ea), \u05dc\u05d4\u05e9\u05d1\u05d9\u05ea \u05d0\u05ea \u05de\u05e1\u05db\u05d9 \u05d4\u05d1\u05d9\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05d9\u05dd \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df \u05d0\u05d5 \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05de\u05d9\u05d5\u05ea\u05e8\u05d5\u05ea, \u05d5\u05dc\u05e9\u05d7\u05d6\u05e8 \u05d0\u05d5\u05ea\u05dd \u05d1\u05db\u05dc \u05e2\u05ea \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05d0\u05d7\u05ea.");
        m.put("CleanYourTV (Beta) runs the CleanYourTV debloat profiles directly on your TV over Local ADB without needing a PC. Choose your TV model (or scan by installed system app packages), pick which bloatware and telemetry apps to disable, and restore them anytime with one tap.", "\u05d4\u05db\u05dc\u05d9 CleanYourTV (\u05d1\u05d8\u05d0) \u05de\u05e8\u05d9\u05e5 \u05d0\u05ea \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9 \u05d4\u05e1\u05e8\u05ea \u05d4\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05d4\u05de\u05d9\u05d5\u05ea\u05e8\u05d5\u05ea \u05e9\u05dc CleanYourTV \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d3\u05e8\u05da ADB \u05de\u05e7\u05d5\u05de\u05d9, \u05dc\u05dc\u05d0 \u05e6\u05d5\u05e8\u05da \u05d1\u05de\u05d7\u05e9\u05d1. \u05d9\u05e9 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d0\u05ea \u05d3\u05d2\u05dd \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 (\u05d0\u05d5 \u05dc\u05e1\u05e8\u05d5\u05e7 \u05dc\u05e4\u05d9 \u05d7\u05d1\u05d9\u05dc\u05d5\u05ea \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05e7\u05e0\u05d5\u05ea), \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d0\u05d9\u05dc\u05d5 \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05de\u05d9\u05d5\u05ea\u05e8\u05d5\u05ea \u05d5\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05d8\u05dc\u05de\u05d8\u05e8\u05d9\u05d4 \u05dc\u05d4\u05e9\u05d1\u05d9\u05ea, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05d7\u05d6\u05e8 \u05d0\u05d5\u05ea\u05df \u05d1\u05db\u05dc \u05e2\u05ea \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05d0\u05d7\u05ea.");
