        m.put("Connecting to local ADB on port 5555 and granting permissions\u2026\n\nIf an \u201cAllow USB debugging?\u201d prompt appears, check \u201cAlways allow\u201d and press Allow.", "\u05de\u05ea\u05d7\u05d1\u05e8 \u05dc-ADB \u05d4\u05de\u05e7\u05d5\u05de\u05d9 \u05d1\u05e4\u05d5\u05e8\u05d8 5555 \u05d5\u05de\u05e2\u05e0\u05d9\u05e7 \u05d4\u05e8\u05e9\u05d0\u05d5\u05ea\u2026\n\n\u05d0\u05dd \u05ea\u05d5\u05e4\u05d9\u05e2 \u05d4\u05d1\u05e7\u05e9\u05d4 \"\u05dc\u05d0\u05e4\u05e9\u05e8 \u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB?\", \u05d9\u05e9 \u05dc\u05e1\u05de\u05df \"\u05dc\u05d0\u05e4\u05e9\u05e8 \u05ea\u05de\u05d9\u05d3\" \u05d5\u05dc\u05dc\u05d7\u05d5\u05e5 \u05e2\u05dc \"\u05d0\u05d9\u05e9\u05d5\u05e8\".");
