        m.put("Continue Watching & DND permission", "\u05d4\u05e8\u05e9\u05d0\u05d4 \u05dc\u05d4\u05de\u05e9\u05da \u05e6\u05e4\u05d9\u05d9\u05d4 \u05d5\u05dc\u05de\u05e6\u05d1 \u05e0\u05d0 \u05dc\u05d0 \u05dc\u05d4\u05e4\u05e8\u05d9\u05e2");
