        m.put("Control Panel actions and items reset to default.", "\u05d4\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05d5\u05d4\u05e4\u05e8\u05d9\u05d8\u05d9\u05dd \u05e9\u05dc \u05dc\u05d5\u05d7 \u05d4\u05d1\u05e7\u05e8\u05d4 \u05d0\u05d5\u05e4\u05e1\u05d5 \u05dc\u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc.");
        m.put("Coocaa OEM TV Home screen", "\u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05e9\u05dc \u05d9\u05e6\u05e8\u05df Coocaa");
        m.put("Cool", "\u05e7\u05d5\u05dc");
        m.put("Could not check for updates.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05d4\u05d9\u05d4 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05dd \u05d9\u05e9 \u05e2\u05d3\u05db\u05d5\u05e0\u05d9\u05dd.");
        m.put("Could not connect to ADB \u2014 enable USB/Network Debugging or use Step 3 / Step 4.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05dc-ADB \u2014 \u05d9\u05e9 \u05dc\u05d4\u05e4\u05e2\u05d9\u05dc \u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB / \u05d1\u05e8\u05e9\u05ea, \u05d0\u05d5 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05e9\u05dc\u05d1 3 / \u05e9\u05dc\u05d1 4.");
        m.put("Could not connect to local ADB on port 5555.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05d4\u05d9\u05d4 \u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05dc-ADB \u05d4\u05de\u05e7\u05d5\u05de\u05d9 \u05d1\u05e4\u05d5\u05e8\u05d8 5555.");
        m.put("Could not connect to local ADB on port 5555.\n\n1. Open Settings \u2192 System \u2192 About and click Build 7 times.\n2. Open Developer Options and turn on USB Debugging / Network Debugging.\n3. Return here and tap Pair / Repair again.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05dc-ADB \u05d4\u05de\u05e7\u05d5\u05de\u05d9 \u05d1\u05e4\u05d5\u05e8\u05d8 5555.\n\n1. \u05d9\u05e9 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d0\u05ea \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u2190 \u05de\u05e2\u05e8\u05db\u05ea \u2190 \u05de\u05d9\u05d3\u05e2 \u05db\u05dc\u05dc\u05d9 \u05d5\u05dc\u05dc\u05d7\u05d5\u05e5 7 \u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05dc \"\u05de\u05e1\u05e4\u05e8 Build\".\n2. \u05d9\u05e9 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d0\u05ea \"\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd\" \u05d5\u05dc\u05d4\u05e4\u05e2\u05d9\u05dc \u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB / \u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1\u05e8\u05e9\u05ea.\n3. \u05d9\u05e9 \u05dc\u05d7\u05d6\u05d5\u05e8 \u05dc\u05db\u05d0\u05df \u05d5\u05dc\u05dc\u05d7\u05d5\u05e5 \u05e9\u05d5\u05d1 \u05e2\u05dc \"\u05e6\u05d9\u05de\u05d5\u05d3 / \u05ea\u05d9\u05e7\u05d5\u05df\".");
        m.put("Could not connect to local ADB on port 5555.\n\nPlease make sure USB Debugging / Network Debugging is turned ON in Developer Options, then try again \u2014 or choose Manual Setup.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05dc-ADB \u05d4\u05de\u05e7\u05d5\u05de\u05d9 \u05d1\u05e4\u05d5\u05e8\u05d8 5555.\n\n\u05d9\u05e9 \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB / \u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1\u05e8\u05e9\u05ea \u05de\u05d5\u05e4\u05e2\u05dc \u05d1\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd \u05d5\u05dc\u05e0\u05e1\u05d5\u05ea \u05e9\u05d5\u05d1 \u2014 \u05d0\u05d5 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d1\u05d4\u05d2\u05d3\u05e8\u05d4 \u05d9\u05d3\u05e0\u05d9\u05ea.");
        m.put("Could not connect to local ADB on port 5555.\nPlease enable USB / Network Debugging in Developer Options and tap Pair / Repair ADB first.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05d4\u05d9\u05d4 \u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05dc-ADB \u05d4\u05de\u05e7\u05d5\u05de\u05d9 \u05d1\u05e4\u05d5\u05e8\u05d8 5555.\n\u05d9\u05e9 \u05dc\u05d4\u05e4\u05e2\u05d9\u05dc \u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB / \u05d1\u05e8\u05e9\u05ea \u05d1\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd, \u05d5\u05dc\u05d0\u05d7\u05e8 \u05de\u05db\u05df \u05dc\u05dc\u05d7\u05d5\u05e5 \u05e2\u05dc \"\u05e6\u05d9\u05de\u05d5\u05d3 / \u05ea\u05d9\u05e7\u05d5\u05df ADB\".");
        m.put("Could not connect to local ADB on port 5555.\nPlease make sure USB / Network Debugging is enabled in Developer Options and tap Pair / Repair ADB first.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05d4\u05d9\u05d4 \u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05dc-ADB \u05d4\u05de\u05e7\u05d5\u05de\u05d9 \u05d1\u05e4\u05d5\u05e8\u05d8 5555.\n\u05d9\u05e9 \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB / \u05d1\u05e8\u05e9\u05ea \u05de\u05d5\u05e4\u05e2\u05dc \u05d1\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd, \u05d5\u05dc\u05d0\u05d7\u05e8 \u05de\u05db\u05df \u05dc\u05dc\u05d7\u05d5\u05e5 \u05e2\u05dc \"\u05e6\u05d9\u05de\u05d5\u05d3 / \u05ea\u05d9\u05e7\u05d5\u05df ADB\".");
        m.put("Could not decode image file", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05e4\u05e2\u05e0\u05d7 \u05d0\u05ea \u05e7\u05d5\u05d1\u05e5 \u05d4\u05ea\u05de\u05d5\u05e0\u05d4");
        m.put("Could not decode image file.", "\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05d4\u05d9\u05d4 \u05dc\u05e4\u05e2\u05e0\u05d7 \u05d0\u05ea \u05e7\u05d5\u05d1\u05e5 \u05d4\u05ea\u05de\u05d5\u05e0\u05d4.");
