        m.put("Custom 5", "\u05de\u05d5\u05ea\u05d0\u05dd \u05d0\u05d9\u05e9\u05d9\u05ea 5");
        m.put("Custom Key Code (Enter Number\u2026)", "\u05e7\u05d5\u05d3 \u05de\u05e7\u05e9 \u05de\u05d5\u05ea\u05d0\u05dd \u05d0\u05d9\u05e9\u05d9\u05ea (\u05d4\u05d6\u05e0\u05ea \u05de\u05e1\u05e4\u05e8\u2026)");
