        m.put("Custom Lock Screen image updated.", "\u05d4\u05ea\u05de\u05d5\u05e0\u05d4 \u05d4\u05de\u05d5\u05ea\u05d0\u05de\u05ea \u05d0\u05d9\u05e9\u05d9\u05ea \u05e9\u05dc \u05de\u05e1\u05da \u05d4\u05e0\u05e2\u05d9\u05dc\u05d4 \u05e2\u05d5\u05d3\u05db\u05e0\u05d4.");
        m.put("Custom background updated.", "\u05d4\u05e8\u05e7\u05e2 \u05d4\u05de\u05d5\u05ea\u05d0\u05dd \u05d0\u05d9\u05e9\u05d9\u05ea \u05e2\u05d5\u05d3\u05db\u05df.");
        m.put("Custom image", "\u05ea\u05de\u05d5\u05e0\u05d4 \u05de\u05d5\u05ea\u05d0\u05de\u05ea \u05d0\u05d9\u05e9\u05d9\u05ea");
        m.put("Custom scene wallpaper updated.", "\u05ea\u05de\u05d5\u05e0\u05ea \u05d4\u05e8\u05e7\u05e2 \u05e9\u05dc \u05d4\u05e1\u05e6\u05e0\u05d4 \u05d4\u05de\u05d5\u05ea\u05d0\u05de\u05ea \u05d0\u05d9\u05e9\u05d9\u05ea \u05e2\u05d5\u05d3\u05db\u05e0\u05d4.");
