        m.put("No saved disabled-app backup was found, and no TV model is selected yet. Choose a TV model first if you want to restore by model profile.", "\u05dc\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d2\u05d9\u05d1\u05d5\u05d9 \u05e9\u05de\u05d5\u05e8 \u05e9\u05dc \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05de\u05d5\u05e9\u05d1\u05ea\u05d5\u05ea, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d0 \u05e0\u05d1\u05d7\u05e8 \u05d3\u05d2\u05dd \u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4. \u05dc\u05e9\u05d7\u05d6\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d4\u05d3\u05d2\u05dd, \u05d9\u05e9 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05e7\u05d5\u05d3\u05dd \u05d3\u05d2\u05dd \u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4.");
        m.put("No saved disabled-app backup was found, and no TV model is selected.\n\nPlease select your TV model first so Restore knows which packages to re-enable.", "\u05dc\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d2\u05d9\u05d1\u05d5\u05d9 \u05e9\u05dc \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05e9\u05d4\u05d5\u05e9\u05d1\u05ea\u05d5, \u05d5\u05dc\u05d0 \u05e0\u05d1\u05d7\u05e8 \u05d3\u05d2\u05dd \u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4.\n\n\u05d9\u05e9 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05ea\u05d7\u05d9\u05dc\u05d4 \u05d0\u05ea \u05d3\u05d2\u05dd \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e9\u05d7\u05d6\u05d5\u05e8 \u05d9\u05d9\u05d3\u05e2 \u05d0\u05d9\u05dc\u05d5 \u05d7\u05d1\u05d9\u05dc\u05d5\u05ea \u05dc\u05d4\u05e4\u05e2\u05d9\u05dc \u05de\u05d7\u05d3\u05e9.");
