        m.put("No stock Android TV / Google TV launcher packages were detected on this TV.", "\u05dc\u05d0 \u05d6\u05d5\u05d4\u05d5 \u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d6\u05d5 \u05d7\u05d1\u05d9\u05dc\u05d5\u05ea \u05e9\u05dc \u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9 \u05e9\u05dc Android TV / Google TV.");
        m.put("No system file picker available on this TV.", "\u05d0\u05d9\u05df \u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d6\u05d5 \u05d1\u05d5\u05d7\u05e8 \u05e7\u05d1\u05e6\u05d9\u05dd \u05e9\u05dc \u05d4\u05de\u05e2\u05e8\u05db\u05ea.");
