        m.put("OK to open  \u00b7  Hold OK to restore", "OK \u05dc\u05e4\u05ea\u05d9\u05d7\u05d4  \u00b7  \u05d4\u05d7\u05d6\u05e7\u05ea OK \u05dc\u05e9\u05d7\u05d6\u05d5\u05e8");
        m.put("OK to open  \u00b7  Hold OK to restore  \u00b7  Back to go back", "OK \u05dc\u05e4\u05ea\u05d9\u05d7\u05d4  \u00b7  \u05d4\u05d7\u05d6\u05e7\u05ea OK \u05dc\u05e9\u05d7\u05d6\u05d5\u05e8  \u00b7  \u05d7\u05d6\u05e8\u05d4 \u05dc\u05de\u05e1\u05da \u05d4\u05e7\u05d5\u05d3\u05dd");
        m.put("OK to switch or edit", "OK \u05dc\u05d4\u05d7\u05dc\u05e4\u05d4 \u05d0\u05d5 \u05dc\u05e2\u05e8\u05d9\u05db\u05d4");
        m.put("ONE-TAP ACTIONS", "\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05d0\u05d7\u05ea");
        m.put("OPTIONS", "\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea");
