        m.put("Off", "\u05db\u05d1\u05d5\u05d9");
        m.put("Off \u2014 Tap to enable Home button remap", "\u05db\u05d1\u05d5\u05d9 \u2014 \u05dc\u05d7\u05d9\u05e6\u05d4 \u05ea\u05e4\u05e2\u05d9\u05dc \u05d0\u05ea \u05d4\u05de\u05d9\u05e4\u05d5\u05d9 \u05de\u05d7\u05d3\u05e9 \u05e9\u05dc \u05dc\u05d7\u05e6\u05df \u05d4\u05d1\u05d9\u05ea");
        m.put("Offline", "\u05dc\u05d0 \u05de\u05d7\u05d5\u05d1\u05e8");
        m.put("On", "\u05de\u05d5\u05e4\u05e2\u05dc");
        m.put("On ", "\u05d1-");
        m.put("On (Default)", "\u05de\u05d5\u05e4\u05e2\u05dc (\u05d1\u05e8\u05d9\u05e8\u05ea \u05de\u05d7\u05d3\u05dc)");
        m.put("On Google TV sets, Wi-Fi networks saved during initial setup belong to com.google.android.tungsten.setupwraith. Disabling setupwraith so the stock Google TV launcher stays dead will delete a Wi-Fi network owned by setupwraith.\n\nBefore disabling setupwraith:\n1. Open Wi-Fi Settings \u2192 select your Wi-Fi network \u2192 Forget network.\n2. Re-connect to your Wi-Fi network (it will now belong to com.android.tv.settings).\n3. Return here and tap \"I Forgot & Re-added Wi-Fi \u2014 Continue\".", "\u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea Google TV, \u05e8\u05e9\u05ea\u05d5\u05ea Wi-Fi \u05e9\u05e0\u05e9\u05de\u05e8\u05d5 \u05d1\u05de\u05d4\u05dc\u05da \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d9\u05ea \u05e9\u05d9\u05d9\u05db\u05d5\u05ea \u05dc-com.google.android.tungsten.setupwraith. \u05d4\u05e9\u05d1\u05ea\u05ea setupwraith, \u05db\u05d3\u05d9 \u05e9\u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9 \u05e9\u05dc Google TV \u05d9\u05d9\u05e9\u05d0\u05e8 \u05de\u05d5\u05e9\u05d1\u05ea, \u05ea\u05de\u05d7\u05e7 \u05e8\u05e9\u05ea Wi-Fi \u05d4\u05e9\u05d9\u05d9\u05db\u05ea \u05dc-setupwraith.\n\n\u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d1\u05ea\u05ea setupwraith:\n1. \u05d9\u05e9 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d0\u05ea \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05d4-Wi-Fi \u2190 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d0\u05ea \u05e8\u05e9\u05ea \u05d4-Wi-Fi \u05e9\u05dc\u05da \u2190 \"\u05e9\u05db\u05d7\u05ea \u05d4\u05e8\u05e9\u05ea\".\n2. \u05d9\u05e9 \u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05de\u05d7\u05d3\u05e9 \u05dc\u05e8\u05e9\u05ea \u05d4-Wi-Fi (\u05de\u05e2\u05db\u05e9\u05d9\u05d5 \u05d4\u05d9\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05e9\u05d9\u05d9\u05db\u05ea \u05dc-com.android.tv.settings).\n3. \u05d9\u05e9 \u05dc\u05d7\u05d6\u05d5\u05e8 \u05dc\u05db\u05d0\u05df \u05d5\u05dc\u05dc\u05d7\u05d5\u05e5 \u05e2\u05dc \"\u05e8\u05e9\u05ea \u05d4-Wi-Fi \u05e0\u05d5\u05e1\u05e4\u05d4 \u05de\u05d7\u05d3\u05e9 (\u05d4\u05de\u05e9\u05da)\".");
        m.put("On Google TV, if you disable setupwraith, make sure your Wi-Fi network was re-added in Wi-Fi Settings.", "\u05d1-Google TV, \u05d0\u05dd setupwraith \u05de\u05d5\u05e9\u05d1\u05ea, \u05d9\u05e9 \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05e8\u05e9\u05ea \u05d4-Wi-Fi \u05e0\u05d5\u05e1\u05e4\u05d4 \u05de\u05d7\u05d3\u05e9 \u05d1\u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05d4-Wi-Fi.");
        m.put("On TCL and Philips Android 11/12 TVs, the OEM firmware often hides the Android Default Home UI and forces the stock launcher when pressing Home. Disabling the stock launcher (Option 2) or enabling the Home Button Fix (Option 3) guarantees pressing Home always opens tvOS Launcher.", "\u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea TCL \u05d5-Philips \u05e2\u05dd Android 11/12, \u05d4\u05e7\u05d5\u05e9\u05d7\u05d4 \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df \u05de\u05e1\u05ea\u05d9\u05e8\u05d4 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d0\u05ea \u05de\u05de\u05e9\u05e7 \u05d1\u05d7\u05d9\u05e8\u05ea \u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05e9\u05dc Android, \u05d5\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05dc\u05d7\u05e6\u05df \u05d4\u05d1\u05d9\u05ea \u05e4\u05d5\u05ea\u05d7\u05ea \u05d0\u05ea \u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9 \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df. \u05d4\u05e9\u05d1\u05ea\u05ea \u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9 (\u05d0\u05e4\u05e9\u05e8\u05d5\u05ea 2) \u05d0\u05d5 \u05d4\u05e4\u05e2\u05dc\u05ea \u05ea\u05d9\u05e7\u05d5\u05df \u05dc\u05d7\u05e6\u05df \u05d4\u05d1\u05d9\u05ea (\u05d0\u05e4\u05e9\u05e8\u05d5\u05ea 3) \u05de\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05e9\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05dc\u05d7\u05e6\u05df \u05d4\u05d1\u05d9\u05ea \u05ea\u05e4\u05ea\u05d7 \u05ea\u05de\u05d9\u05d3 \u05d0\u05ea tvOS Launcher.");
        m.put("On TCL, Philips, and Google TVs, OEM firmware often forces the stock launcher when pressing Home. Follow the steps below so pressing Home always opens tvOS Launcher, then click Continue.", "\u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea \u05e9\u05dc TCL, \u200fPhilips \u05d5-Google TV, \u05d4\u05e7\u05d5\u05e9\u05d7\u05d4 \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df \u05de\u05d7\u05d6\u05d9\u05e8\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05d1\u05d5\u05ea \u05d0\u05ea \u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9 \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05dc\u05d7\u05e6\u05df \u05d4\u05d1\u05d9\u05ea. \u05d9\u05e9 \u05dc\u05d1\u05e6\u05e2 \u05d0\u05ea \u05d4\u05e9\u05dc\u05d1\u05d9\u05dd \u05d4\u05d1\u05d0\u05d9\u05dd \u05db\u05d3\u05d9 \u05e9\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05dc\u05d7\u05e6\u05df \u05d4\u05d1\u05d9\u05ea \u05ea\u05e4\u05ea\u05d7 \u05ea\u05de\u05d9\u05d3 \u05d0\u05ea tvOS Launcher, \u05d5\u05dc\u05d0\u05d7\u05e8 \u05de\u05db\u05df \u05dc\u05dc\u05d7\u05d5\u05e5 \u05e2\u05dc \"\u05d4\u05de\u05e9\u05da\".");
        m.put("On the Lock Screen, only Clock, Date, and Greeting are shown above your selected backgrounds. Pressing any remote button returns to where you were before.", "\u05d1\u05de\u05e1\u05da \u05d4\u05e0\u05e2\u05d9\u05dc\u05d4 \u05de\u05d5\u05e6\u05d2\u05d9\u05dd \u05e8\u05e7 \u05d4\u05e9\u05e2\u05d5\u05df, \u05d4\u05ea\u05d0\u05e8\u05d9\u05da \u05d5\u05d4\u05d1\u05e8\u05db\u05d4 \u05de\u05e2\u05dc \u05d4\u05e8\u05e7\u05e2\u05d9\u05dd \u05e9\u05e0\u05d1\u05d7\u05e8\u05d5. \u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05dc\u05d7\u05e6\u05df \u05db\u05dc\u05e9\u05d4\u05d5 \u05d1\u05e9\u05dc\u05d8 \u05de\u05d7\u05d6\u05d9\u05e8\u05d4 \u05dc\u05de\u05e1\u05da \u05d4\u05e7\u05d5\u05d3\u05dd.");
        m.put("On this TV", "\u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d6\u05d5");
        m.put("On \u2014 Pressing Home launches tvOS Launcher", "\u05de\u05d5\u05e4\u05e2\u05dc \u2014 \u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05dc\u05d7\u05e6\u05df \u05d4\u05d1\u05d9\u05ea \u05e4\u05d5\u05ea\u05d7\u05ea \u05d0\u05ea tvOS Launcher");
        m.put("One photo and a grid of app banners", "\u05ea\u05de\u05d5\u05e0\u05d4 \u05d0\u05d7\u05ea \u05d5\u05e8\u05e9\u05ea \u05e9\u05dc \u05d1\u05d0\u05e0\u05e8\u05d9\u05dd \u05e9\u05dc \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea");
        m.put("One scene has to stay on.", "\u05e1\u05e6\u05e0\u05d4 \u05d0\u05d7\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05de\u05d5\u05e4\u05e2\u05dc\u05ea.");
        m.put("One wallpaper has to stay on.", "\u05ea\u05de\u05d5\u05e0\u05ea \u05e8\u05e7\u05e2 \u05d0\u05d7\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05de\u05d5\u05e4\u05e2\u05dc\u05ea.");
        m.put("Online", "\u05de\u05d7\u05d5\u05d1\u05e8 \u05dc\u05d0\u05d9\u05e0\u05d8\u05e8\u05e0\u05d8");
        m.put("Open", "\u05e4\u05ea\u05d9\u05d7\u05d4");
        m.put("Open Android Default Home Settings", "\u05e4\u05ea\u05d9\u05d7\u05ea \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05de\u05e1\u05da \u05d4\u05d1\u05d9\u05ea \u05e9\u05dc Android");
        m.put("Open Android TV Settings\u2026", "\u05e4\u05ea\u05d9\u05d7\u05ea \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea Android TV\u2026");
        m.put("Open Developer Options / TV Settings\u2026", "\u05e4\u05ea\u05d9\u05d7\u05ea \u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd / \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4\u2026");
        m.put("Open Developer Options and turn on USB Debugging / Network Debugging to complete switching to Persistent ADB Mode.", "\u05d9\u05e9 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d0\u05ea \"\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd\" \u05d5\u05dc\u05d4\u05e4\u05e2\u05d9\u05dc \u05d0\u05ea \"\u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB\" / \"\u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1\u05e8\u05e9\u05ea\" \u05db\u05d3\u05d9 \u05dc\u05d4\u05e9\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05e2\u05d1\u05e8 \u05dc\u05de\u05e6\u05d1 ADB \u05e7\u05d1\u05d5\u05e2.");
        m.put("Open Developer Options and turn on USB Debugging / Network Debugging.", "\u05d9\u05e9 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d0\u05ea \"\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd\" \u05d5\u05dc\u05d4\u05e4\u05e2\u05d9\u05dc \u05d0\u05ea \"\u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1-USB\" / \"\u05e0\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d0\u05d2\u05d9\u05dd \u05d1\u05e8\u05e9\u05ea\".");
        m.put("Open Developer Options\u2026", "\u05e4\u05ea\u05d9\u05d7\u05ea \u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd\u2026");
        m.put("Open System File Picker\u2026", "\u05e4\u05ea\u05d9\u05d7\u05ea \u05d1\u05d5\u05d7\u05e8 \u05d4\u05e7\u05d1\u05e6\u05d9\u05dd \u05e9\u05dc \u05d4\u05de\u05e2\u05e8\u05db\u05ea\u2026");
        m.put("Open TV Ambient Mode / Screensaver (or built-in fallback)", "\u05e4\u05ea\u05d9\u05d7\u05ea \u05de\u05e6\u05d1 \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 / \u05e9\u05d5\u05de\u05e8 \u05d4\u05de\u05e1\u05da \u05e9\u05dc \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 (\u05d0\u05d5 \u05d4\u05d7\u05dc\u05d5\u05e4\u05d4 \u05d4\u05de\u05d5\u05d1\u05e0\u05d9\u05ea)");
        m.put("Open on a phone or computer on the same Wi-Fi:\n\n", "\u05d9\u05e9 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d1\u05d8\u05dc\u05e4\u05d5\u05df \u05d0\u05d5 \u05d1\u05de\u05d7\u05e9\u05d1 \u05e9\u05de\u05d7\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05d0\u05d5\u05ea\u05d4 \u05e8\u05e9\u05ea Wi-Fi:\n\n");
        m.put("Open system selector (if supported by TV) \u203a", "\u05e4\u05ea\u05d9\u05d7\u05ea \u05d4\u05d1\u05d5\u05e8\u05e8 \u05e9\u05dc \u05d4\u05de\u05e2\u05e8\u05db\u05ea (\u05d0\u05dd \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05ea\u05d5\u05de\u05db\u05ea) \u2039");
        m.put("Or open ", "\u05d0\u05d5 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d0\u05ea ");
