        m.put("\u26a0\ufe0f Core system package \u2014 disabling may affect system stability", "\u26a0\ufe0f \u05d7\u05d1\u05d9\u05dc\u05ea \u05dc\u05d9\u05d1\u05d4 \u05e9\u05dc \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u2014 \u05d4\u05e9\u05d1\u05ea\u05d4 \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05d9\u05e6\u05d9\u05d1\u05d5\u05ea \u05d4\u05de\u05e2\u05e8\u05db\u05ea");
        m.put("\u26a0\ufe0f Detected: Your current Wi-Fi network IS owned by setupwraith (cname=com.google.android.tungsten.setupwraith).\n\n", "\u26a0\ufe0f \u05d6\u05d5\u05d4\u05d4: \u05e8\u05e9\u05ea \u05d4-Wi-Fi \u05d4\u05e0\u05d5\u05db\u05d7\u05d9\u05ea \u05e9\u05dc\u05da \u05e9\u05d9\u05d9\u05db\u05ea \u05dc-setupwraith (cname=com.google.android.tungsten.setupwraith).\n\n");
        m.put("\u26a0\ufe0f Manual Debloat Warning", "\u26a0\ufe0f \u05d0\u05d6\u05d4\u05e8\u05d4: \u05d4\u05e1\u05e8\u05d4 \u05d9\u05d3\u05e0\u05d9\u05ea \u05e9\u05dc \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05de\u05d9\u05d5\u05ea\u05e8\u05d5\u05ea");
        m.put("\u26a0\ufe0f Security Warning:\n\nKeep Alive monitors and restores permissions if your TV turns them off in the background.\n\nWithout WRITE_SECURE_SETTINGS, Keep Alive requires Network Debugging (ADB on port 5555) to stay enabled on your home network. For better security, run Pair / Repair ADB in Secure Mode first so WRITE_SECURE_SETTINGS is granted and port 5555 can be closed.\n\nEnable Keep Alive anyway?", "\u26a0\ufe0f \u05d0\u05d6\u05d4\u05e8\u05ea \u05d0\u05d1\u05d8\u05d7\u05d4:\n\n\u05d4\u05e9\u05de\u05d9\u05e8\u05d4 \u05e2\u05dc \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05e2\u05d5\u05e7\u05d1\u05ea \u05d0\u05d7\u05e8 \u05d4\u05d4\u05e8\u05e9\u05d0\u05d5\u05ea \u05d5\u05de\u05e9\u05d7\u05d6\u05e8\u05ea \u05d0\u05d5\u05ea\u05df \u05d0\u05dd \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05de\u05db\u05d1\u05d4 \u05d0\u05d5\u05ea\u05df \u05d1\u05e8\u05e7\u05e2.\n\n\u05dc\u05dc\u05d0 \u05d4\u05d4\u05e8\u05e9\u05d0\u05d4 WRITE_SECURE_SETTINGS, \u05d4\u05e9\u05de\u05d9\u05e8\u05d4 \u05e2\u05dc \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05de\u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05d0\u05ea \u05e0\u05d9\u05e4\u05d5\u05d9 \u05d4\u05d1\u05d0\u05d2\u05d9\u05dd \u05d1\u05e8\u05e9\u05ea (ADB \u05d1\u05e4\u05d5\u05e8\u05d8 5555) \u05de\u05d5\u05e4\u05e2\u05dc \u05d1\u05e8\u05e9\u05ea \u05d4\u05d1\u05d9\u05ea\u05d9\u05ea. \u05dc\u05d0\u05d1\u05d8\u05d7\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05de\u05d5\u05de\u05dc\u05e5 \u05dc\u05d4\u05e8\u05d9\u05e5 \u05e7\u05d5\u05d3\u05dd \u05d0\u05ea \"\u05e6\u05d9\u05de\u05d5\u05d3 / \u05ea\u05d9\u05e7\u05d5\u05df ADB\" \u05d1\u05de\u05e6\u05d1 \u05de\u05d0\u05d5\u05d1\u05d8\u05d7, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d4\u05e8\u05e9\u05d0\u05d4 WRITE_SECURE_SETTINGS \u05ea\u05d5\u05e2\u05e0\u05e7 \u05d5\u05d0\u05e4\u05e9\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05dc\u05e1\u05d2\u05d5\u05e8 \u05d0\u05ea \u05e4\u05d5\u05e8\u05d8 5555.\n\n\u05dc\u05d4\u05e4\u05e2\u05d9\u05dc \u05e9\u05de\u05d9\u05e8\u05d4 \u05e2\u05dc \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05d1\u05db\u05dc \u05d6\u05d0\u05ea?");
        m.put("\u26a0\ufe0f Your Wi-Fi network is currently owned by setupwraith. Before disabling setupwraith, open Wi-Fi Settings, Forget your Wi-Fi network, and re-connect so Wi-Fi stays saved.", "\u26a0\ufe0f \u05e8\u05e9\u05ea \u05d4-Wi-Fi \u05e9\u05dc\u05da \u05de\u05e9\u05d5\u05d9\u05db\u05ea \u05db\u05e8\u05d2\u05e2 \u05dc-setupwraith. \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d1\u05ea\u05ea setupwraith, \u05d9\u05e9 \u05dc\u05e4\u05ea\u05d5\u05d7 \u05d0\u05ea \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05d4-Wi-Fi, \u05dc\u05d1\u05d7\u05d5\u05e8 \"\u05e9\u05db\u05d7\u05ea \u05d4\u05e8\u05e9\u05ea\" \u05d5\u05dc\u05d4\u05ea\u05d7\u05d1\u05e8 \u05d0\u05dc\u05d9\u05d4 \u05de\u05d7\u05d3\u05e9, \u05db\u05d3\u05d9 \u05e9\u05e8\u05e9\u05ea \u05d4-Wi-Fi \u05ea\u05d9\u05e9\u05d0\u05e8 \u05e9\u05de\u05d5\u05e8\u05d4.");
        m.put("\u2705 Re-added Wi-Fi (Continue)", "\u2705 \u05e8\u05e9\u05ea \u05d4-Wi-Fi \u05e0\u05d5\u05e1\u05e4\u05d4 \u05de\u05d7\u05d3\u05e9 (\u05d4\u05de\u05e9\u05da)");
        m.put("\u2b05  .. (Parent folder)", "\u27a1  .. (\u05ea\u05d9\u05e7\u05d9\u05d9\u05ea \u05d4\u05d0\u05d1)");
        m.put("\u2b05  Back to storage folders", "\u27a1  \u05d7\u05d6\u05e8\u05d4 \u05dc\u05ea\u05d9\u05e7\u05d9\u05d5\u05ea \u05d4\u05d0\u05d7\u05e1\u05d5\u05df");
        m.put("\ud83d\udccb Browse / Search All 341 TV Models", "\ud83d\udccb \u05e2\u05d9\u05d5\u05df / \u05d7\u05d9\u05e4\u05d5\u05e9 \u05d1\u05db\u05dc 341 \u05d3\u05d2\u05de\u05d9 \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4");
        m.put("\ud83d\udccb Browse All 341 TV Models", "\ud83d\udccb \u05e2\u05d9\u05d5\u05df \u05d1\u05db\u05dc 341 \u05d3\u05d2\u05de\u05d9 \u05d4\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4");
        m.put("\ud83d\udcf6 Open Wi-Fi Settings\u2026", "\ud83d\udcf6 \u05e4\u05ea\u05d9\u05d7\u05ea \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05d4-Wi-Fi\u2026");
        m.put("\ud83d\udcf6 Wi-Fi Settings\u2026", "\ud83d\udcf6 \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea Wi-Fi\u2026");
        m.put("\ud83d\udd0d Filter system apps\u2026", "\ud83d\udd0d \u05e1\u05d9\u05e0\u05d5\u05df \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05de\u05e2\u05e8\u05db\u05ea\u2026");
        m.put("\ud83d\udd0d Scan Installed System Apps to Find Matching Model", "\ud83d\udd0d \u05e1\u05e8\u05d9\u05e7\u05ea \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05e7\u05e0\u05d5\u05ea \u05dc\u05d0\u05d9\u05ea\u05d5\u05e8 \u05d3\u05d2\u05dd \u05ea\u05d5\u05d0\u05dd");
        m.put("\ud83d\udd0d Scan Installed System Apps via ADB", "\ud83d\udd0d \u05e1\u05e8\u05d9\u05e7\u05ea \u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d5\u05ea \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05d5\u05ea\u05e7\u05e0\u05d5\u05ea \u05d3\u05e8\u05da ADB");
        m.put("\ud83d\udd0d Search / Filter by brand or model\u2026", "\ud83d\udd0d \u05d7\u05d9\u05e4\u05d5\u05e9 / \u05e1\u05d9\u05e0\u05d5\u05df \u05dc\u05e4\u05d9 \u05d9\u05e6\u05e8\u05df \u05d0\u05d5 \u05d3\u05d2\u05dd\u2026");
        m.put("\ud83d\udd0d Search\u2026", "\ud83d\udd0d \u05d7\u05d9\u05e4\u05d5\u05e9\u2026");
        m.put("\ud83d\uded1 Critical System Service", "\ud83d\uded1 \u05e9\u05d9\u05e8\u05d5\u05ea \u05de\u05e2\u05e8\u05db\u05ea \u05e7\u05e8\u05d9\u05d8\u05d9");
        m.put("\ud83d\uded1 Critical system service \u2014 protected (cannot be disabled)", "\ud83d\uded1 \u05e9\u05d9\u05e8\u05d5\u05ea \u05de\u05e2\u05e8\u05db\u05ea \u05e7\u05e8\u05d9\u05d8\u05d9 \u2014 \u05de\u05d5\u05d2\u05df (\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d4\u05e9\u05d1\u05d9\u05ea)");
        m.put("\ud83d\udee1\ufe0f Skip setupwraith", "\ud83d\udee1\ufe0f \u05d3\u05d9\u05dc\u05d5\u05d2 \u05e2\u05dc setupwraith");
